using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace CleanArch.Generators;

/// <summary>
/// Emits a repository skeleton for each interface marked with
/// [GenerateRepository] — removes the boilerplate of wiring a new
/// repository by hand. Emit-time only; the generated file is meant
/// to be extended.
/// </summary>
[Generator]
public sealed class RepositoryGenerator : IIncrementalGenerator
{
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static ctx =>
            ctx.AddSource("GenerateRepositoryAttribute.g.cs",
                SourceText.From("""
                    // <auto-generated/>
                    namespace CleanArch.Generators;

                    [System.AttributeUsage(System.AttributeTargets.Interface)]
                    public sealed class GenerateRepositoryAttribute
                        : System.Attribute;
                    """, Encoding.UTF8)));

        var interfaces = context.SyntaxProvider
            .ForAttributeWithMetadataName(
                "CleanArch.Generators.GenerateRepositoryAttribute",
                static (node, _) => node is InterfaceDeclarationSyntax,
                static (ctx, _) =>
                    (InterfaceDeclarationSyntax)ctx.TargetNode)
            .Collect();

        context.RegisterSourceOutput(interfaces, static (spc, ifaces) =>
        {
            foreach (var iface in ifaces)
            {
                var name = iface.Identifier.Text.TrimStart('I');
                var entityName = name.EndsWith("Repository")
                    ? name.Substring(0, name.Length - "Repository".Length)
                    : name;

                spc.AddSource($"{entityName}Repository.g.cs",
                    SourceText.From($$"""
                        // <auto-generated/>
                        #nullable enable
                        namespace CleanArch.Infrastructure.Common.Persistence;

                        /// <summary>
                        /// Generated repository skeleton for
                        /// {{iface.Identifier.Text}} — fill in the
                        /// provider-specific persistence calls.
                        /// </summary>
                        public sealed partial class {{entityName}}Repository
                        {
                        }
                        """, Encoding.UTF8));
            }
        });
    }
}
